-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "元素"
L["rm.era.shaman.elemental.Description"] = "從 10 級起的元素（大部分天賦點數在元素）；綜合 Icy Veins 與 Wowhead。以地震術中斷施法並收掉即將死亡的目標。移動時：烈焰震擊，否則冰霜震擊。單人且目標在近戰範圍內時：目標生命力高於 30% 時使用地震術，然後近戰。三個以上敵人時：你在近戰範圍內時放下火焰新星圖騰與熔岩圖騰，以及閃電鏈。元素專精或節能施法期間使用閃電鏈，否則使用閃電箭。提醒：閃電之盾、團隊以外使用石化武器、灼熱圖騰或熔岩圖騰、法力之泉圖騰或治療之泉圖騰、閃電鏈就緒時使用元素專精、低於 30% 時使用自然迅捷與治療波、拉怪後治療。驅散、淨化術與降級施法由你自行處理。"
L["rm.era.shaman.elemental.simulator.Name"] = "元素，閃電鏈冷卻結束即施放（模擬器）"
L["rm.era.shaman.elemental.simulator.Description"] = "模擬器 的元素清單，作為推薦的元素內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。即使只有一個目標，閃電鏈冷卻結束即施放，元素專精生效時使用地震術，否則使用閃電箭。比推薦的內建循環更快，但耗魔多得多；中斷、圖騰與提醒相同。"
L["rm.era.shaman.enhancement.Name"] = "增強"
L["rm.era.shaman.enhancement.Description"] = "1–60 級，也適用於專家模式與獨行模式伺服器，也是所有天賦點數未集中於某一天賦樹的薩滿的循環；綜合 Icy Veins、Wowhead 與 模擬器。從遠處以閃電箭拉怪；以地震術中斷施法。團隊中只使用風暴打擊與冰霜震擊（減益效果欄位）。三個以上敵人與你交戰時，放下火焰新星圖騰與熔岩圖騰。接著是風暴打擊、風暴打擊的減益效果存在時或收尾時使用地震術、烈焰震擊能完整持續時使用烈焰震擊、法力至少一半時使用地震術，以及目標不在攻擊範圍內時使用閃電箭。提醒：單人時石化武器、地城中風怒武器、閃電之盾、大地之力圖騰、灼熱圖騰、風怒圖騰或風之優雅圖騰、法力之泉圖騰或治療之泉圖騰、拉怪後與緊急時的治療。石爪圖騰、地縛圖騰、圖騰輪替與種族技能列出但預設關閉；驅散、淨化術與清除圖騰由你自行處理。"
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "增強，烈焰震擊優先（Warcraft Tavern）"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Warcraft Tavern 的增強，作為推薦的增強內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。一學會風怒武器就使用，風暴打擊，任何直接傷害震擊之前先使用烈焰震擊，然後在你的威脅值低時使用地震術，隊伍中威脅值變高後改用冰霜震擊；怪群時使用熔岩圖騰與閃電鏈。圖騰與提醒與推薦的內建循環相同。"
L["rm.era.shaman.restoration.Name"] = "恢復"
L["rm.era.shaman.restoration.Description"] = "從 10 級起的恢復（大部分天賦點數在恢復）；綜合 Icy Veins 與 Wowhead。對你的友方目標：自然迅捷生效時使用治療波，低於 30% 時使用自然迅捷，低於 40% 時使用次級治療波，消毒術或祛病術，附近有三名隊伍成員低於 85% 時使用治療鍊，否則低於 90% 時使用治療波。目標為敵人時則進行攻擊：地震術中斷、怪群時使用閃電鏈、烈焰震擊、從遠處使用閃電箭、近戰。提醒：單人時閃電之盾與石化武器、隊伍中法力之潮圖騰、法力之泉圖騰、大地之力圖騰、灼熱圖騰。要治療誰、降級施法以及戰慄圖騰或清除圖騰由你自行處理；在坦克身上維持治療之路列出但預設關閉。"
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "恢復，治療鍊優先（Warcraft Tavern）"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Warcraft Tavern 的恢復，作為推薦的恢復內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。任何低於 90% 的人都以治療鍊治療，即將死亡的人則用次級治療波；治療波只用於擁有治療之路、被指派治療坦克的治療者（列出但預設關閉）。驅除、對敵人的傷害與圖騰提醒與推薦的內建循環相同。"
L["rm.forever.shaman.elemental.Name"] = "元素"
L["rm.forever.shaman.elemental.Description"] = "當元素是你的主要天賦樹且已投入 21 點（熔岩爆發所在層）後的遠程元素，依據 Icy Veins（在此之前，由增強內建循環執行所有指南都推薦的近戰混合打法）。以閃電箭拉怪（怪群時用閃電鏈），移動時只施放瞬發法術，三個以上敵人時使用火焰新星與閃電鏈，維持烈焰震擊，熔岩爆發冷卻結束即使用，若學會風暴打擊則使用風暴打擊與地震術，隊伍中節能施法觸發時使用火焰新星，然後是閃電箭。提醒：護盾、武器灌注、灼熱圖騰或熔岩圖騰、隊伍圖騰、精通元素、中斷施法。在永久版本中，插件看不到生命力與法力，因此治療自己與停下來回復法力由你決定。由你自行處理：以地縛圖騰放風箏、冰霜震擊、淨化術與其他圖騰。"
L["rm.forever.shaman.enhancement.Name"] = "增強（Icy Veins）"
L["rm.forever.shaman.enhancement.Description"] = "增強近戰，適用於 1 至 60 級，也是學會熔岩爆發或法力之潮圖騰之前所有薩滿的預設循環。從遠處以閃電箭拉怪，接著風暴打擊冷卻結束即使用，氣漩武器疊滿五層時施放瞬發閃電箭，三個以上敵人時使用火焰新星（需已放下火焰圖騰）與烈焰震擊，在風暴打擊減益效果期間使用地震術，隊伍中使用烈焰震擊，以及地震術冷卻結束即使用；目標不在攻擊範圍內時以閃電箭填補空檔。在永久版本中，插件看不到生命力與法力，因此治療自己與停下來回復法力由你決定（Wowhead 內建循環則改為節省法力）。提醒：武器灌注（風怒武器，否則火舌武器，再否則石化武器）、水之盾或閃電之盾、地震術中斷、灼熱圖騰或熔岩圖騰、隊伍圖騰、先知之怒、石爪圖騰。由你自行處理：圖騰預設組合、冰霜震擊、淨化術與其他圖騰。"
L["rm.forever.shaman.enhancement.wowhead.Name"] = "增強，節省法力（Wowhead）"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Wowhead 與 Mobalytics 的節省法力增強：主要靠自動攻擊輸出，只在強化風暴打擊的法力回復效果不在時使用風暴打擊，循環中不使用地震術（震擊用於拉怪與中斷），隊伍中或面對怪群時使用灼熱圖騰，並在冷卻結束時使用火焰新星。武器灌注、護盾與中斷提醒與 Icy Veins 內建循環相同。如果你的法力不夠用，請選擇它而非那個內建循環。這是推薦的增強內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.forever.shaman.restoration.Name"] = "恢復"
L["rm.forever.shaman.restoration.Description"] = "當恢復是你的主要天賦樹且已投入 16 點（法力之潮圖騰所在層）後的治療，依據 Icy Veins。友方目標時：使用自然迅捷後施放瞬發治療波、消毒術與祛病術、對沒有激流的目標使用激流、隊伍中使用治療鍊，其餘使用治療波。透過選取目標來決定要治療誰；在永久版本中，插件看不到生命力與法力，因此何時使用自然迅捷與次級治療波由你決定。目標為敵對且無人需要治療時：怪群使用火焰新星與閃電鏈，若學會風暴打擊則使用風暴打擊與地震術，對精英與首領使用烈焰震擊、閃電箭，然後近戰。提醒：水之盾、地震術中斷、法力之潮圖騰與隊伍增益圖騰。由你自行處理：降級施法、其他圖騰、淨化術與幽魂之狼。"
L["rm.mop.shaman.elemental.Name"] = "推薦"
L["rm.mop.shaman.elemental.Description"] = "推薦 10 級起的元素使用，在元素專精下選用。Wowhead 的順序：以閃電箭開場（有狂怒釋放時用熔岩爆發），有狂怒釋放時使用釋放元素能量，對會存活的目標在烈焰震擊缺少或即將結束時使用烈焰震擊，對有烈焰震擊的目標使用熔岩爆發（每次熔岩奔騰也使用），元素衝擊，閃電之盾六層充能且烈焰震擊還剩 6 秒時使用大地震擊，兩個敵人時使用閃電鏈，閃電箭。四個以上敵人與你交戰時：近戰時使用熔岩圖騰、免費的熔岩爆發、卓越術期間使用熔岩光束、閃電鏈。移動時只顯示瞬發法術。提醒：閃電之盾、火舌武器、灼熱圖騰、對精英與首領使用火元素圖騰、精通元素、熔岩爆發後使用卓越術、先祖迅捷、隊伍中使用風暴鞭笞圖騰與嗜血術、削風術、為法力使用雷霆風暴、生命力低時使用薩滿之怒與星界轉移。地震術與土元素圖騰列出但預設關閉。由你自行處理：靈行者之賜、對其他目標施放烈焰震擊以及站位。"
L["rm.mop.shaman.enhancement.Name"] = "推薦"
L["rm.mop.shaman.enhancement.Description"] = "推薦 10 級起的增強使用，在增強專精下選用。Wowhead 的順序：衝向目標時使用釋放元素能量，接著有狂怒釋放時使用釋放元素能量，五層氣漩武器時使用元素衝擊與閃電箭（或在下一次揮擊還要超過一秒時於三層穿插施放），卓越術期間使用風暴衝擊，風暴打擊（26 級前為原始之擊），熔岩暴擊，釋放火舌能量期間使用烈焰震擊，釋放元素能量，大地震擊。兩個以上敵人與你交戰時：以閃電鏈取代閃電箭，以熔岩暴擊擴散烈焰震擊，四個起使用火焰新星，六個起使用熔岩圖騰。提醒：閃電之盾、主手風怒武器與副手火舌武器、灼熱圖騰、火元素圖騰、野性之魂、風暴打擊後使用卓越術、精通元素、先祖迅捷、隊伍中使用風暴鞭笞圖騰與嗜血術、削風術、生命力低時使用薩滿之怒與星界轉移。土元素圖騰列出但預設關閉。"
L["rm.mop.shaman.enhancement.icyveins.Name"] = "熔岩暴擊優先（Icy Veins）"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "預設關閉；與推薦的增強內建循環使用相同的切換條件，因此要使用它，請啟用它並停用推薦的循環。Icy Veins 的順序：風暴打擊，然後在消耗氣漩武器之前使用熔岩暴擊，五層時使用閃電箭，或在下一次揮擊前能命中時從三層起使用，釋放元素能量然後烈焰震擊，大地震擊。四個以上敵人時以熔岩暴擊擴散烈焰震擊並使用火焰新星；怪群時以閃電鏈取代閃電箭。戰鬥中薩滿之怒冷卻結束即建議使用；其他提醒與推薦的內建循環相同。"
L["rm.mop.shaman.enhancement.simulator.Name"] = "每層都穿插施放（模擬器）"
L["rm.mop.shaman.enhancement.simulator.Description"] = "預設關閉；與推薦的增強內建循環使用相同的切換條件，因此要使用它，請啟用它並停用推薦的循環。模擬器為會在揮擊之間抓時機施法的玩家提供的清單：只要施法能在下一次主手揮擊前完成，不論有幾層氣漩武器都使用閃電箭、元素衝擊或閃電鏈，烈焰震擊缺少時也使用釋放元素能量，大地震擊只在少於兩層時使用。提醒與推薦的內建循環相同。"
L["rm.mop.shaman.restoration.Name"] = "推薦"
L["rm.mop.shaman.restoration.Description"] = "推薦 10 級起的恢復使用，在恢復專精下選用。治療你的友方目標（Rotation Master 無法選擇要治療誰）：先祖迅捷生效時使用強效治療波，低於 35% 時使用洶湧治療，有魔法或詛咒效果時使用淨化靈魂，附近有三名盟友受傷時先使用釋放元素能量再使用治癒之雨，激流，隊伍受傷時使用治療鍊，低於 60% 時使用強效治療波，低於 90% 時使用治療波。選取可攻擊的目標時改為造成傷害（烈焰震擊、熔岩爆發、元素衝擊、閃電箭）。提醒：水之盾、大地生命武器、對你的專注目標施放大地之盾、有人受傷時使用治療之泉圖騰、法力之潮圖騰、隊伍承受大量傷害時使用療癒之潮圖騰、精通元素或先祖導引、對生命力低的目標使用先祖迅捷、移動時使用靈行者之賜、嗜血術、削風術。卓越術與靈魂連結圖騰列出但預設關閉：在你的團隊指派時使用它們。"
L["rm.mop.shaman.restoration.hekili.Name"] = "生命力階梯（Hekili）"
L["rm.mop.shaman.restoration.hekili.Description"] = "預設關閉；與推薦的恢復內建循環使用相同的切換條件，因此要使用它，請啟用它並停用推薦的循環。Hekili 的清單會在你的目標身上維持大地之盾與激流，治療之泉圖騰與治癒之雨一不在就重新施放，然後依 40 碼內隊伍的平均生命力進行治療：低於 80% 時使用治療鍊，目標低於 70% 時使用治療波，低於 60% 時使用強效治療波，低於 40% 時使用洶湧治療，療癒之潮圖騰、先祖導引與法力之潮圖騰也在同一階梯上。選取可攻擊的目標時會造成傷害並使用大地震擊。"
L["rm.mop.shaman.unspecialized.Name"] = "未選擇專精"
L["rm.mop.shaman.unspecialized.Description"] = "適用於 1 至 9 級，以及尚未選擇專精的任何薩滿；選擇專精後由各專精的內建循環接手。從遠處以閃電箭拉怪，你獨自一人且生命力低時使用洶湧治療，原始之擊，大地震擊，不在近戰範圍時使用閃電箭。維持閃電之盾。"
L["rm.retail.shaman.elemental.Name"] = "暴雪戰鬥助手"
L["rm.retail.shaman.elemental.Description"] = "推薦至暗之夜的元素專精使用。在戰鬥中，遊戲現在會對插件隱藏烈焰震擊、你的增益效果、元能、冷卻時間與生命力，因此它會顯示暴雪自己的戰鬥助手建議（一鍵循環），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：戰鬥中的卓越術、火元素或風暴元素以及自然迅捷、移動中使用靈行者之賜、兩波拉怪之間的閃電之盾與天怒（暴雪的建議會維持你的武器與護盾灌注）、對可中斷的施法使用削風術（只會在遊戲允許讀取該施法的場合亮起）、戰鬥中只要就緒就使用星界轉移（正式版中生命力是隱藏的，因此何時使用由你決定）。"
L["rm.retail.shaman.elemental.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.shaman.elemental.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft 的施放順序需要讀取烈焰震擊、元素大師與風暴守護者，而至暗之夜會在戰鬥中隱藏它們；正式版中元能是隱藏的，因此消耗技能只等待自身的消耗，而不是等元能接近滿值。拉怪前使用風暴守護者與熔岩爆發。面對三個以上交戰中的敵人時：風暴守護者，先祖迅捷，烈焰震擊，風暴守護者生效時使用閃電鏈，元素衝擊，地震術，熔岩奔騰觸發時使用熔岩爆發，暴風雨，閃電鏈。否則：風暴守護者，先祖迅捷，元素大師以外在剩餘最後 30% 時刷新烈焰震擊與電流燃炎，使用熔岩爆發觸發元素大師，元素大師期間使用暴風雨與風暴守護者強化的閃電箭，元素大師期間使用元素衝擊或大地震擊，電流燃炎，暴風雨，移動中使用烈焰震擊或冰霜震擊，只要負擔得起就使用元素衝擊或大地震擊，閃電箭。提醒：風暴守護者用掉後使用卓越術、火元素或風暴元素、靈行者之賜，以及共用提醒。"
L["rm.retail.shaman.enhancement.Name"] = "暴雪戰鬥助手"
L["rm.retail.shaman.enhancement.Description"] = "推薦至暗之夜的增強專精使用。顯示暴雪的戰鬥助手建議（它會消耗氣漩武器、維持烈焰震擊，並處理翻湧圖騰與裂地浩劫），並在你施法或沒有選取敵人時停止。提醒它未包含的內容：戰鬥中的卓越術、末日之風與野性之魂、兩波拉怪之間的閃電之盾與天怒（暴雪的建議會維持風怒武器）、削風術、星界轉移。"
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "風暴使者參考（SimulationCraft）"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "僅供參考，預設關閉：SimulationCraft 的風暴使者清單（Icy Veins 與 Wowhead 的看法一致）需要讀取烈焰震擊、閃電轟擊、暴擊烈焰與冷卻計時，而至暗之夜會在戰鬥中隱藏它們。面對三個以上交戰中的敵人時：為取得增益效果使用閃電轟擊，氣漩武器達到 10 層時使用暴風雨，達到 9 層時使用閃電鏈，閃電轟擊，熔岩暴擊，裂地浩劫。接著氣漩武器達到 9 層時使用原初風暴，烈焰震擊消失時使用電流燃炎或烈焰震擊，裂地浩劫，為取得增益效果使用閃電轟擊，為暴擊烈焰使用熔岩暴擊，風暴衝擊，達到 10 層時使用暴風雨或閃電箭（電流燃炎或閃電轟擊即將就緒時為 8 層），兩層充能時使用風暴打擊，熔岩暴擊，風暴打擊，電流燃炎，閃電轟擊，達到 5 層時使用閃電箭，烈焰震擊。提醒：末日之風、末日之風以外使用卓越術、野性之魂，以及共用提醒。"
L["rm.retail.shaman.enhancement.totemic.Name"] = "圖騰師參考（SimulationCraft）"
L["rm.retail.shaman.enhancement.totemic.Description"] = "僅供參考，預設關閉：SimulationCraft 的圖騰師清單需要讀取烈焰震擊、炙手、環繞之火、閃電轟擊與末日之風，而至暗之夜會在戰鬥中隱藏它們。面對三個以上交戰中的敵人時：閃電轟擊，氣漩武器達到 5 層時使用閃電鏈。接著烈焰震擊消失時使用電流燃炎或烈焰震擊，翻湧圖騰，裂地浩劫，有炙手或環繞之火時使用熔岩暴擊，為取得增益效果使用閃電轟擊，達到 10 層時使用原初風暴，風暴衝擊，末日之風期間使用閃電轟擊與風暴打擊，達到 5 層時使用閃電箭，閃電轟擊，熔岩暴擊，風暴打擊，電流燃炎，烈焰震擊。提醒與風暴使者參考循環相同。"
L["rm.retail.shaman.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.shaman.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是薩滿的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個薩滿內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "至暗之夜的恢復專精，僅供參考：暴雪的戰鬥助手不涵蓋治療者，遊戲在戰鬥中會隱藏所有人的生命力，而 Rotation Master 選擇的是法術而不是目標，因此它會針對你目前的目標依就緒情況排列你的治療技能，決定要治療誰則交給你。友方目標：治療之泉圖騰，生命流溢，在隊伍中使用治癒之雨，翻湧圖騰，激流，在隊伍中使用治療鍊，治療波。敵人：烈焰震擊消失時使用烈焰震擊，熔岩爆發，閃電箭。提醒：兩波拉怪之間的水之盾、對友方目標使用大地之盾與天怒；戰鬥中的自然迅捷；組隊戰鬥中的療癒之潮圖騰與靈魂連結圖騰；削風術；星界轉移。"
L["rm.sod.shaman.elemental.Name"] = "元素（探索賽季）"
L["rm.sod.shaman.elemental.Description"] = "探索賽季從 10 級起的元素（大部分天賦點數在元素）；綜合 模擬器 第 6 階段、Wowhead 與 Icy Veins。以地震術中斷施法。移動時：烈焰震擊、閃電之盾八層充能時使用地震術、能量激增觸發時使用熔岩爆發或閃電鏈。三個以上敵人時：烈焰震擊、閃電鏈、火焰新星、熔岩爆發、八層充能時使用地震術、熔岩圖騰。接著能量激增觸發時使用熔岩爆發、維持烈焰震擊、你的烈焰震擊持續期間使用熔岩爆發、八層充能時使用地震術、兩個敵人時使用閃電鏈、閃電箭。提醒：為了燃燒使用火舌武器、閃電之盾、對自己施放大地之盾、獸群首領之靈、野性之魂、薩滿之怒、元素專精、圖騰。飾品、圖騰投射、驅散與淨化術由你自行處理。"
L["rm.sod.shaman.enhancement.Name"] = "增強（探索賽季）"
L["rm.sod.shaman.enhancement.Description"] = "探索賽季，1–60 級，符文會在你紋刻後納入使用，雙持或雙手武器皆可，也是沒有其他內建循環適用時所有探索賽季薩滿的預設循環；綜合 模擬器 第 6 階段、Icy Veins 與 Wowhead。以烈焰震擊拉怪；以地震術中斷施法。三個以上敵人時：熔岩圖騰、火焰新星（需有火焰圖騰）、四層氣漩武器時使用閃電鏈、烈焰震擊。接著五層氣漩武器時使用熔岩爆發、風暴打擊、熔岩暴擊、五層時使用閃電箭、烈焰震擊能完整持續時使用烈焰震擊、地震術、熔岩爆裂、從遠處使用閃電箭。提醒：風怒武器（之前用石化武器）、有熔岩暴擊時在副手武器上使用火舌武器（否則用風怒武器；絕不用於盾牌；Icy Veins 雙手都用風怒武器的步驟列出但預設關閉）、水之盾或閃電之盾、獸群首領之靈、野性之魂、法力低於 65% 時使用薩滿之怒、圖騰、先祖導引。圖騰投射、驅散與淨化術由你自行處理。"
L["rm.sod.shaman.restoration.Name"] = "恢復（探索賽季）"
L["rm.sod.shaman.restoration.Description"] = "探索賽季從 10 級起的恢復（大部分天賦點數在恢復）；綜合 Icy Veins 與 Wowhead。對你的友方目標：低於 40% 時先使用激流再使用次級治療波，消毒術或祛病術，附近有三名隊伍成員低於 85% 時使用治癒之雨，兩名時使用治療鍊（能量激增觸發時立即使用），低於 95% 時使用激流以觸發治療之潮，低於 90% 時使用治療波。目標為敵人時則進行攻擊。提醒：水之盾（之前用閃電之盾）、對你的友方目標或自己施放大地之盾、薩滿之怒、法力之潮圖騰、法力之泉圖騰與大地之力圖騰。要治療誰以及戰慄圖騰或清除圖騰由你自行處理。"
L["rm.sod.shaman.tank.Name"] = "坦克（探索賽季，大地之道）"
L["rm.sod.shaman.tank.Description"] = "探索賽季的坦克，在已紋刻大地之道時選用；綜合 Icy Veins、Wowhead、模擬器 與 Warcraft Tavern。以烈焰震擊拉怪。以地震術嘲諷近戰範圍內沒有攻擊你的目標，並中斷施法。兩個以上敵人時：熔岩爆裂、烈焰震擊、五層氣漩武器或能量激增觸發時使用閃電鏈、五層時使用火焰新星。接著維持烈焰震擊、能量激增觸發時或烈焰震擊持續期間使用熔岩爆發、風暴打擊、地震術、五層時使用閃電箭、熔岩爆裂、冰霜震擊。提醒：石化武器、閃電之盾、對自己施放獸群首領之靈、野性之魂、薩滿之怒、灼熱圖騰或熔岩圖騰，以及隊伍圖騰。"
L["rm.tbc.shaman.elemental.icyveins.Name"] = "元素（Icy Veins & 模擬器）"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "針對元素天賦樹的施法型元素。閃電箭為填充技能；閃電鏈在精通元素期間、法力至少 40% 時的節能施法期間，或法力高於 80% 時自由施放；烈焰震擊只在移動時使用；地震術用於中斷；成群敵人時使用火焰新星、閃電鏈與熔岩圖騰。在閃電鏈之前，若目標位於近戰範圍內，就交由自動攻擊處理以節省法力。提醒：水之盾或閃電之盾、武器灌注、憤怒圖騰（長時間戰鬥則用灼熱圖騰）、風懲圖騰、法力之泉圖騰、戰鬥後的圖騰的呼喚、精通元素以及嗜血術/英勇氣概。"
L["rm.tbc.shaman.elemental.nextaction.Name"] = "元素（NextActionTBC）"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "NextActionTBC 的元素，作為推薦的 Icy Veins 元素內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。維持目標身上的烈焰震擊，只有在面對兩個以上敵人且法力高於 30% 時才使用閃電鏈，否則使用閃電箭。會提醒你閃電之盾、武器灌注、精通元素以及嗜血術/英勇氣概；圖騰由你手動處理。"
L["rm.tbc.shaman.elemental.wowhead.Name"] = "元素（Wowhead）"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "Wowhead 的元素，作為推薦的 Icy Veins 元素內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。70 級時閃電鏈冷卻結束即施放，其間穿插閃電箭（升級期間只在精通元素或節能施法時施放閃電鏈），烈焰震擊只在移動時使用，以地震術收掉會在施法完成前死亡的目標。圖騰、護盾與冷卻技能提醒與 Icy Veins 版本相同。"
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "增強（Icy Veins）"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "增強近戰，適用於 1 至 70 級，也是沒有其他內建循環適用時所有薩滿的預設循環。從遠處以閃電箭拉怪，以地震術中斷施法，附近有三個以上敵人時放下火焰新星圖騰與熔岩圖騰，接著是風暴打擊、風暴打擊的減益效果存在時使用地震術、對會存活較久的目標使用烈焰震擊、冷卻結束即使用地震術，以及目標不在攻擊範圍內時使用閃電箭。獨立提醒：武器灌注、水之盾或閃電之盾、大地之力圖騰、風怒圖騰（隊伍中）或風之優雅圖騰（單人）、長時間戰鬥時的灼熱圖騰、水之圖騰、薩滿之怒、首領戰時的嗜血術/英勇氣概、單人時的石爪圖騰與土元素圖騰。火元素圖騰是預設關閉的選擇性步驟。圖騰擺放、鬼魂之狼與治療由你自行處理。"
L["rm.tbc.shaman.enhancement.simulator.Name"] = "增強（Wowhead & 模擬器）"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "70 級團隊副本的圖騰輪替模型，作為推薦的 Icy Veins 增強內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。風暴打擊、穿插火焰新星圖騰、烈焰震擊一消失就重新施放、以地震術作為主要震擊，只有在目標超出攻擊範圍時才使用閃電箭。提醒會輪替風怒圖騰與風之優雅圖騰、維持灼熱圖騰，在法力不足時使用薩滿之怒，並與 Icy Veins 版本共用武器灌注、護盾與圖騰維持提醒。"
L["rm.tbc.shaman.restoration.Name"] = "恢復"
L["rm.tbc.shaman.restoration.Description"] = "恢復天賦樹的治療，作用於你的友方目標（沒有目標時則是你自己）：緊急時使用自然迅捷搭配治療波或次級治療波、消毒術與祛病術、對你的專注目標施放大地之盾，附近有三名盟友受傷時使用治療鍊，否則使用治療波。目標為敵對時改用烈焰震擊與閃電箭來單人練功。提醒：水之盾、對專注目標施放大地之盾（請將坦克設為專注目標）、法力之潮圖騰、隊伍中的法力之泉圖騰與大地之力圖騰、嗜血術/英勇氣概。要治療誰以及使用哪個等級由你決定。"
